hazard_name = #{hazardName}, place_type = #{placeType}, dept_id = #{deptId}, related_equip_ids = #{relatedEquipIds}, chemical_name = #{chemicalName}, cas_no = #{casNo}, critical_qty_ton = #{criticalQtyTon}, actual_qty_ton = #{actualQtyTon}, r_index = #{rIndex}, major_hazard_grade = #{majorHazardGrade}, dow_mf = #{dowMf}, combustion_heat_kj = #{combustionHeatKj}, map_x = #{mapX}, map_y = #{mapY}, on_duty_count = #{onDutyCount}, risk_level = #{riskLevel}, physicochemical_props = #{physicochemicalProps}, emergency_measures = #{emergencyMeasures}, ppe_requirements = #{ppeRequirements}, update_time = CURRENT_TIMESTAMP
