SELECT dr.drill_id, dr.drill_no, dr.trigger_type, dr.alert_id, dr.hazard_id, h.hazard_name, dr.accident_type, dr.leak_mass_kg, dr.wind_direction, dr.wind_speed_ms, dr.tnt_equivalent_kg, dr.r1_death_m, dr.r2_serious_m, dr.r3_minor_m, dr.r4_property_m, dr.affected_equip_json::text AS affected_equip_json, dr.affected_staff_count, dr.action_card_markdown, dr.create_by, dr.create_time FROM ehs_emergency_drill dr LEFT JOIN ehs_hazard_profile h ON dr.hazard_id = h.hazard_id
AND dr.hazard_id = #{hazardId}
ORDER BY dr.drill_id DESC
